/* =====================================================================
   ERP_Demo - SQL Server | Dữ liệu mô phỏng FIX CỨNG (~49.000 dòng)
   Bảng: DMVT, DMKho, DMDT, Ton_Dau, CT, CTCT (theo ERD)
   Loai_Ct: 1 = Nhập mua (NCC), 2 = Xuất bán (Khách hàng)
   Loai_Dt: 1 = Khách hàng, 2 = Nhà cung cấp
   Quy tắc: nhập kho ngày 1-10, xuất kho ngày 11-28 mỗi tháng -> tồn không âm;
            Tien = So_Luong * Don_Gia; NCC chỉ giao đúng nhóm hàng;
            Ton_Dau 2026 = Ton_Dau 2025 + Nhập - Xuất 2025.
   Chạy toàn bộ file trong SSMS (Execute). Cuối file có 7 câu kiểm tra (kỳ vọng = 0).
   ===================================================================== */

/* ERP_Demo - tạo database và bảng theo ERD */
IF DB_ID(N'Quan_Ly_Kho_Hang') IS NULL
    CREATE DATABASE Quan_Ly_Kho_Hang;
GO
USE Quan_Ly_Kho_Hang;
GO
SET NOCOUNT ON;
GO
DROP TABLE IF EXISTS dbo.CTCT;
DROP TABLE IF EXISTS dbo.CT;
DROP TABLE IF EXISTS dbo.Ton_Dau;
DROP TABLE IF EXISTS dbo.DMDT;
DROP TABLE IF EXISTS dbo.DMKho;
DROP TABLE IF EXISTS dbo.DMVT;
GO

CREATE TABLE dbo.DMVT (
    Ma_vt     NVARCHAR(20)  NOT NULL,
    Ten_vt    NVARCHAR(200) NOT NULL,
    Dvt       NVARCHAR(20)  NULL,
    Loai_Vt   INT           NOT NULL DEFAULT 1,   -- 1 Thép, 2 Điện, 3 Nhựa, 4 Bao bì, 5 Hóa chất
    Dinh_Chi  INT           NOT NULL DEFAULT 0,
    CONSTRAINT PK_DMVT PRIMARY KEY (Ma_vt)
);

CREATE TABLE dbo.DMKho (
    Ma_Kho    NVARCHAR(20)  NOT NULL,
    Ten_Kho   NVARCHAR(200) NOT NULL,
    Dinh_Chi  INT           NOT NULL DEFAULT 0,
    CONSTRAINT PK_DMKho PRIMARY KEY (Ma_Kho)
);

CREATE TABLE dbo.DMDT (
    Ma_Dt     NVARCHAR(20)  NOT NULL,
    Ten_Dt    NVARCHAR(200) NOT NULL,
    Loai_Dt   INT           NOT NULL,             -- 1 Khách hàng, 2 Nhà cung cấp
    Dinh_Chi  INT           NOT NULL DEFAULT 0,
    CONSTRAINT PK_DMDT PRIMARY KEY (Ma_Dt),
    CONSTRAINT CK_DMDT_Loai CHECK (Loai_Dt IN (1,2))
);

CREATE TABLE dbo.Ton_Dau (
    Nam       INT           NOT NULL,
    Ky        INT           NOT NULL,
    Ma_Kho    NVARCHAR(20)  NOT NULL,
    Ma_Vt     NVARCHAR(20)  NOT NULL,
    So_Luong  NUMERIC(18,2) NOT NULL DEFAULT 0,
    Tien      NUMERIC(18,2) NOT NULL DEFAULT 0,
    -- ERD chỉ đánh PK ở Nam, Ky; thực tế phải gồm Ma_Kho, Ma_Vt để định danh dòng
    CONSTRAINT PK_Ton_Dau PRIMARY KEY (Nam, Ky, Ma_Kho, Ma_Vt),
    CONSTRAINT FK_TonDau_Kho FOREIGN KEY (Ma_Kho) REFERENCES dbo.DMKho(Ma_Kho),
    CONSTRAINT FK_TonDau_Vt  FOREIGN KEY (Ma_Vt)  REFERENCES dbo.DMVT(Ma_vt),
    CONSTRAINT CK_TonDau_SL  CHECK (So_Luong >= 0)
);

CREATE TABLE dbo.CT (
    So_Ct     NVARCHAR(20)  NOT NULL,
    Ngay_Ct   DATETIME      NOT NULL,
    Ma_Dt     NVARCHAR(20)  NOT NULL,
    Ma_Kho    NVARCHAR(20)  NOT NULL,
    Loai_Ct   INT           NOT NULL,             -- 1 Nhập mua, 2 Xuất bán
    Dien_Giai NVARCHAR(500) NULL,
    Dinh_Chi  INT           NOT NULL DEFAULT 0,
    CONSTRAINT PK_CT PRIMARY KEY (So_Ct),
    CONSTRAINT FK_CT_DT  FOREIGN KEY (Ma_Dt)  REFERENCES dbo.DMDT(Ma_Dt),
    CONSTRAINT FK_CT_Kho FOREIGN KEY (Ma_Kho) REFERENCES dbo.DMKho(Ma_Kho),
    CONSTRAINT CK_CT_Loai CHECK (Loai_Ct IN (1,2))
);

CREATE TABLE dbo.CTCT (
    So_Ct     NVARCHAR(20)  NOT NULL,
    Stt_Dong  INT           NOT NULL,
    Ma_Vt     NVARCHAR(20)  NOT NULL,
    So_Luong  NUMERIC(18,2) NOT NULL,
    Don_Gia   NUMERIC(18,2) NOT NULL,
    Tien      NUMERIC(18,2) NOT NULL,
    CONSTRAINT PK_CTCT PRIMARY KEY (So_Ct, Stt_Dong),
    CONSTRAINT FK_CTCT_CT FOREIGN KEY (So_Ct) REFERENCES dbo.CT(So_Ct),
    CONSTRAINT FK_CTCT_Vt FOREIGN KEY (Ma_Vt) REFERENCES dbo.DMVT(Ma_vt),
    CONSTRAINT CK_CTCT_SL   CHECK (So_Luong > 0),
    CONSTRAINT CK_CTCT_Tien CHECK (Tien = So_Luong * Don_Gia)
);
GO
