USE ERP_Demo;
GO
SET NOCOUNT ON;
GO
CREATE INDEX IX_CT_Ngay      ON dbo.CT(Ngay_Ct) INCLUDE (Loai_Ct, Ma_Kho, Ma_Dt);
CREATE INDEX IX_CT_Ma_Dt     ON dbo.CT(Ma_Dt);
CREATE INDEX IX_CT_Ma_Kho    ON dbo.CT(Ma_Kho);
CREATE INDEX IX_CTCT_Ma_Vt   ON dbo.CTCT(Ma_Vt) INCLUDE (So_Luong, Tien);
CREATE INDEX IX_TonDau_Ma_Vt ON dbo.Ton_Dau(Ma_Vt);
GO

-- Tự động kết chuyển khóa sổ tồn đầu kỳ cho các Kỳ 2..12 (năm 2025) và Kỳ 2..10 (năm 2026)
SET NOCOUNT ON;
IF OBJECT_ID('tempdb..#PS_KetChuyen') IS NOT NULL DROP TABLE #PS_KetChuyen;

SELECT c.Ma_Kho, d.Ma_Vt, YEAR(c.Ngay_Ct) AS Nam, MONTH(c.Ngay_Ct) AS Thang,
       SUM(CASE WHEN c.Loai_Ct = 1 THEN d.So_Luong ELSE -d.So_Luong END) AS Delta_SL,
       SUM(CASE WHEN c.Loai_Ct = 1 THEN d.Tien ELSE -d.Tien END) AS Delta_Tien
INTO #PS_KetChuyen
FROM dbo.CTCT d
INNER JOIN dbo.CT c ON d.So_Ct = c.So_Ct
WHERE c.Dinh_Chi = 0
GROUP BY c.Ma_Kho, d.Ma_Vt, YEAR(c.Ngay_Ct), MONTH(c.Ngay_Ct);

CREATE INDEX IX_PS_KC ON #PS_KetChuyen(Nam, Ma_Kho, Ma_Vt, Thang);

DECLARE @Ky_KC INT = 2;
WHILE @Ky_KC <= 12
BEGIN
    SELECT 2025, @Ky_KC, td.Ma_Kho, td.Ma_Vt,
           td.So_Luong + ISNULL(ps.SL, 0),
           CASE WHEN td.Tien + ISNULL(ps.Tien, 0) < 0 THEN 0 ELSE td.Tien + ISNULL(ps.Tien, 0) END
    FROM dbo.Ton_Dau td
    LEFT JOIN (
        SELECT Ma_Kho, Ma_Vt, SUM(Delta_SL) AS SL, SUM(Delta_Tien) AS Tien
        FROM #PS_KetChuyen WHERE Nam = 2025 AND Thang < @Ky_KC
        GROUP BY Ma_Kho, Ma_Vt
    ) ps ON td.Ma_Kho = ps.Ma_Kho AND td.Ma_Vt = ps.Ma_Vt
    WHERE td.Nam = 2025 AND td.Ky = 1;

    IF @Ky_KC <= 10
    BEGIN
        SELECT 2026, @Ky_KC, td.Ma_Kho, td.Ma_Vt,
               td.So_Luong + ISNULL(ps.SL, 0),
               CASE WHEN td.Tien + ISNULL(ps.Tien, 0) < 0 THEN 0 ELSE td.Tien + ISNULL(ps.Tien, 0) END
        FROM dbo.Ton_Dau td
        LEFT JOIN (
            SELECT Ma_Kho, Ma_Vt, SUM(Delta_SL) AS SL, SUM(Delta_Tien) AS Tien
            FROM #PS_KetChuyen WHERE Nam = 2026 AND Thang < @Ky_KC
            GROUP BY Ma_Kho, Ma_Vt
        ) ps ON td.Ma_Kho = ps.Ma_Kho AND td.Ma_Vt = ps.Ma_Vt
        WHERE td.Nam = 2026 AND td.Ky = 1;
    END

    SET @Ky_KC = @Ky_KC + 1;
END
DROP TABLE #PS_KetChuyen;
GO

-- Số dòng từng bảng
SELECT 'DMVT' AS Bang, COUNT(*) AS So_Dong FROM dbo.DMVT
UNION ALL SELECT 'DMKho',   COUNT(*) FROM dbo.DMKho
UNION ALL SELECT 'DMDT',    COUNT(*) FROM dbo.DMDT
UNION ALL SELECT 'Ton_Dau', COUNT(*) FROM dbo.Ton_Dau
UNION ALL SELECT 'CT',      COUNT(*) FROM dbo.CT
UNION ALL SELECT 'CTCT',    COUNT(*) FROM dbo.CTCT;
GO

-- Kiểm tra tính đúng đắn: cột Ket_Qua kỳ vọng = 0
;WITH mv AS (
    SELECT ct.Ma_Kho, d.Ma_Vt, ct.Ngay_Ct, ct.So_Ct,
           dq = d.So_Luong * CASE ct.Loai_Ct WHEN 1 THEN 1 ELSE -1 END
    FROM   dbo.CTCT d JOIN dbo.CT ct ON ct.So_Ct = d.So_Ct
), run AS (
    SELECT mv.Ma_Kho, mv.Ma_Vt,
           ton = ISNULL(td.So_Luong, 0)
               + SUM(mv.dq) OVER (PARTITION BY mv.Ma_Kho, mv.Ma_Vt
                                  ORDER BY mv.Ngay_Ct, mv.So_Ct ROWS UNBOUNDED PRECEDING)
    FROM   mv
    LEFT JOIN dbo.Ton_Dau td ON td.Nam = 2025 AND td.Ky = 1 AND td.Ma_Kho = mv.Ma_Kho AND td.Ma_Vt = mv.Ma_Vt
)
SELECT N'1. Tồn kho âm theo dòng thời gian' AS Kiem_Tra, COUNT(*) AS Ket_Qua FROM run WHERE ton < 0
UNION ALL
SELECT N'2. CTCT có Tien <> SL x Đơn giá', COUNT(*) FROM dbo.CTCT WHERE Tien <> So_Luong * Don_Gia
UNION ALL
SELECT N'3. Chứng từ không có dòng chi tiết', COUNT(*) FROM dbo.CT ct
       WHERE NOT EXISTS (SELECT 1 FROM dbo.CTCT d WHERE d.So_Ct = ct.So_Ct)
UNION ALL
SELECT N'4. Phiếu nhập: NCC không đúng nhóm hàng', COUNT(*)
       FROM dbo.CT ct JOIN dbo.CTCT d ON d.So_Ct = ct.So_Ct JOIN dbo.DMVT v ON v.Ma_vt = d.Ma_Vt
       WHERE ct.Loai_Ct = 1 AND (CAST(SUBSTRING(ct.Ma_Dt, 4, 3) AS INT) - 1) / 12 + 1 <> v.Loai_Vt
UNION ALL
SELECT N'5. Loại đối tượng sai (nhập <> NCC, xuất <> KH)', COUNT(*)
       FROM dbo.CT ct JOIN dbo.DMDT dt ON dt.Ma_Dt = ct.Ma_Dt
       WHERE (ct.Loai_Ct = 1 AND dt.Loai_Dt <> 2) OR (ct.Loai_Ct = 2 AND dt.Loai_Dt <> 1)
UNION ALL
SELECT N'6. Giao dịch với kho/đối tượng/vật tư đã đình chỉ', COUNT(*)
       FROM dbo.CT ct
       JOIN dbo.CTCT d  ON d.So_Ct = ct.So_Ct
       JOIN dbo.DMKho k ON k.Ma_Kho = ct.Ma_Kho
       JOIN dbo.DMDT dt ON dt.Ma_Dt = ct.Ma_Dt
       JOIN dbo.DMVT v  ON v.Ma_vt = d.Ma_Vt
       WHERE k.Dinh_Chi = 1 OR dt.Dinh_Chi = 1 OR v.Dinh_Chi = 1
UNION ALL
SELECT N'7. Ton_Dau 2026 không khớp (Tồn 2025 + Nhập - Xuất)', COUNT(*)
       FROM dbo.Ton_Dau t26
       JOIN dbo.Ton_Dau t25 ON t25.Nam = 2025 AND t25.Ky = 1 AND t25.Ma_Kho = t26.Ma_Kho AND t25.Ma_Vt = t26.Ma_Vt
       OUTER APPLY (SELECT q = SUM(d.So_Luong * CASE ct.Loai_Ct WHEN 1 THEN 1 ELSE -1 END)
                    FROM dbo.CTCT d JOIN dbo.CT ct ON ct.So_Ct = d.So_Ct
                    WHERE ct.Ma_Kho = t25.Ma_Kho AND d.Ma_Vt = t25.Ma_Vt AND ct.Ngay_Ct < '20260101') m
       WHERE t26.Nam = 2026 AND t26.Ky = 1 AND t26.So_Luong <> t25.So_Luong + ISNULL(m.q, 0);
GO
